/* Proc-id ranges by anchor-site species code (procs are sorted so each
 * species' processes are contiguous): scan only the bucket matching
 * st->species[site]. */
static const int32_t v2_bucket_begin[5] = {0,2400,2400,2400,2400};

/* ---- generic matcher ---- */
static int v2_match(const Lattice *lat, const State *st, int site,
                    const V2Proc *pr)
{
    const V2Pattern *pt = &v2_patterns[pr->pat];
    const int8_t *R = V2_OPS[pr->op];
    const int16_t *c0 = &lat->site_ijk[3 * site];
    for (int32_t r = 0; r < pt->delta_n; ++r) {
        const V2DeltaRow *dr = &v2_delta_rows[pt->delta_begin + r];
        int32_t di = R[0]*dr->di + R[1]*dr->dj + R[2]*dr->dk;
        int32_t dj = R[3]*dr->di + R[4]*dr->dj + R[5]*dr->dk;
        int32_t dk = R[6]*dr->di + R[7]*dr->dj + R[8]*dr->dk;
        int32_t rs = lattice_site_at_ijk(lat, c0[0]+di, c0[1]+dj, c0[2]+dk);
        /* Delta sites must EXIST with the exact before-state; the stub's
         * 255 sentinel never equals a real species code. */
        if (st->species[rs] != dr->before) return 0;
    }
    for (int32_t r = 0; r < pt->ctx_n; ++r) {
        const V2CtxRow *cr = &v2_ctx_rows[pt->ctx_begin + r];
        int32_t di = R[0]*cr->di + R[1]*cr->dj + R[2]*cr->dk;
        int32_t dj = R[3]*cr->di + R[4]*cr->dj + R[5]*cr->dk;
        int32_t dk = R[6]*cr->di + R[7]*cr->dj + R[8]*cr->dk;
        int32_t rs = lattice_site_at_ijk(lat, c0[0]+di, c0[1]+dj, c0[2]+dk);
        uint8_t v = st->species[rs];
        uint8_t p = cr->pred;
        if (p == V2_PRED_EMPTY) {
            /* Harvest-side EMPTY cannot distinguish a vacant lattice site
             * from vacuum beyond the slab; match either. */
            if (v != SP_VACANT && v != 255u) return 0;
        } else if (p == V2_PRED_OCC_ANY) {
            if (v == SP_VACANT || v == 255u) return 0;
        } else if (v != p) {
            return 0;
        }
    }
    return 1;
}

void touchup_a(const Lattice *lat, const State *st, AvailSites *as, int site)
{
    if (!lat->site_grid || !lat->site_ijk) return;  /* grid not built */
    uint8_t sp = st->species[site];
    if (sp >= 4u) return;
    for (int32_t p = v2_bucket_begin[sp]; p < v2_bucket_begin[sp + 1]; ++p) {
        if (v2_match(lat, st, site, &v2_procs[p]))
            avail_sites_add(as, p, site);
    }
}

/* ---- generic apply + per-proc wrappers ----
 *
 * The runtime calls pylatkmc_apply_table[proc](st, lat, site) — a
 * signature frozen by the committed v0.3 proclists — so each proc gets
 * a one-line wrapper binding its proc id into the generic apply. */
typedef struct { int v_origin; int v_dest; } HopOutcome;
typedef HopOutcome (*ApplyFn)(State *st, const Lattice *lat, int site);

static HopOutcome v2_apply(State *st, const Lattice *lat, int32_t proc,
                           int32_t site)
{
    const V2Proc *pr = &v2_procs[proc];
    const V2Pattern *pt = &v2_patterns[pr->pat];
    const int8_t *R = V2_OPS[pr->op];
    const int16_t *c0 = &lat->site_ijk[3 * site];
    StateAction acts[V2_MAX_DELTA];
    for (int32_t r = 0; r < pt->delta_n; ++r) {
        const V2DeltaRow *dr = &v2_delta_rows[pt->delta_begin + r];
        int32_t di = R[0]*dr->di + R[1]*dr->dj + R[2]*dr->dk;
        int32_t dj = R[3]*dr->di + R[4]*dr->dj + R[5]*dr->dk;
        int32_t dk = R[6]*dr->di + R[7]*dr->dj + R[8]*dr->dk;
        acts[r].site   = lattice_site_at_ijk(lat, c0[0]+di, c0[1]+dj, c0[2]+dk);
        acts[r].before = dr->before;
        acts[r].after  = dr->after;
    }
    (void)state_apply_actions(st, acts, pt->delta_n, SP_VACANT);
    HopOutcome ho = { -1, -1 };
    if (pt->v_origin_row >= 0) ho.v_origin = acts[pt->v_origin_row].site;
    if (pt->v_dest_row   >= 0) ho.v_dest   = acts[pt->v_dest_row].site;
    return ho;
}

#define V2W(n) static HopOutcome v2w_##n(State *st, const Lattice *lat, int site) { return v2_apply(st, lat, n, site); }
